}

.product-info h3 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

.product-price {
  font-weight: 500;
  color: var(--text-main);
}

/* Deals */
.deals-banner {
  background: var(--primary);
  color: white;
  padding: 3rem;
  border-radius: 1rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
