 @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

 :root {
   --primary: #1a1a1a;
   --secondary: #f4f4f4;
   --accent: #3b82f6;
   --text-main: #111827;
   --text-muted: #6b7280;
   --bg: #ffffff;
   --card-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
 }

 * {
   margin: 0;
   padding: 0;
   box-sizing: border-box;
 }

 body {
   font-family: 'Inter', sans-serif;
   color: var(--text-main);
   background-color: var(--bg);
   line-height: 1.5;
 }

 .container {
   max-width: 1200px;
   margin: 0 auto;
   padding: 0 2rem;
 }

 /* Navbar */
 nav {
   height: 80px;
   display: flex;
   align-items: center;
   justify-content: space-between;
   border-bottom: 1px solid #e5e7eb;
   position: sticky;
   top: 0;
   background: white;
   z-index: 100;
 }

 .logo {
   font-size: 1.5rem;
   font-weight: 700;
   letter-spacing: -0.025em;
 }

 .nav-links {
   display: flex;
   gap: 2rem;
 }

 .nav-links a {
   text-decoration: none;
   color: var(--text-main);
   font-weight: 500;
   font-size: 0.9375rem;
 }

 .nav-actions {
   display: flex;
   gap: 1.5rem;
   align-items: center;
 }

 /* Hero Section */
 .hero {
   padding: 4rem 0;
   background-color: var(--secondary);
   margin-bottom: 4rem;
 }

 .hero-content {
   display: flex;
   align-items: center;
   gap: 4rem;
 }

 .hero-text {
   flex: 1;
 }

 .hero-text h1 {
   font-size: 3.5rem;
   font-weight: 800;
   line-height: 1.1;
   margin-bottom: 1.5rem;
   letter-spacing: -0.05em;
 }

 .hero-text p {
   font-size: 1.125rem;
   color: var(--text-muted);
   margin-bottom: 2rem;
 }

 .hero-image {
   flex: 1;
   height: 400px;
   background: #ddd;
   border-radius: 1rem;
   overflow: hidden;
   display: flex;
   align-items: center;
   justify-content: center;
   background: linear-gradient(135deg, #e2e8f0 0%, #cbd5e1 100%);
 }

 .btn {
   display: inline-block;
   padding: 0.75rem 1.5rem;
   border-radius: 0.5rem;
   font-weight: 600;
   text-decoration: none;
   transition: all 0.2s;
   cursor: pointer;
 }

 .btn-primary {
   background-color: var(--primary);
   color: white;
 }

 .btn-primary:hover {
   opacity: 0.9;
 }

 /* Section headers */
 section {
   margin-bottom: 5rem;
 }

 .section-header {
   display: flex;
   justify-content: space-between;
   align-items: flex-end;
   margin-bottom: 2rem;
 }

 .section-header h2 {
   font-size: 1.875rem;
   font-weight: 700;
 }

 /* Product Grid */
 .product-grid {
   display: grid;
   grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
   gap: 2rem;
 }

 .product-card {
   transition: transform 0.2s;
 }

 .product-card:hover {
   transform: translateY(-4px);
 }

 .product-image {
   aspect-ratio: 1;
   background-color: var(--secondary);
   border-radius: 0.75rem;
   margin-bottom: 1rem;
   display: flex;
   align-items: center;
   justify-content: center;
   font-weight: 500;
   color: var(--text-muted);
 }

 .product-info h3 {
   font-size: 1rem;
   font-weight: 600;
   margin-bottom: 0.25rem;
 }

 .product-price {
   font-weight: 500;
   color: var(--text-main);
 }

 /* Deals */
 .deals-banner {
   background: var(--primary);
   color: white;
   padding: 3rem;
   border-radius: 1rem;
   display: flex;
   justify-content: space-between;
   align-items: center;
 }

 .deals-text h2 {
   font-size: 2.25rem;
   margin-bottom: 0.5rem;
 }

 /* Editorial */
 .editorial-grid {
   display: grid;
   grid-template-columns: 1fr 1fr;
   gap: 2rem;
 }

 .editorial-card {
   position: relative;
   height: 500px;
   border-radius: 1rem;
   overflow: hidden;
   display: flex;
   flex-direction: column;
   justify-content: flex-end;
   padding: 2.5rem;
   color: white;
 }

 .editorial-card::before {
   content: '';
   position: absolute;
   top: 0;
   left: 0;
   right: 0;
   bottom: 0;
   background: linear-gradient(to top, rgba(0,0,0,0.7) 0%, rgba(0,0,0,0) 100%);
   z-index: 1;
 }

 .editorial-card * {
   position: relative;
   z-index: 2;
 }

 .editorial-card h3 {
   font-size: 1.5rem;
   margin-bottom: 0.5rem;
 }

 /* Footer */
 footer {
   border-top: 1px solid #e5e7eb;
   padding: 4rem 0 2rem;
   background: #fafafa;
 }

 .footer-grid {
   display: grid;
   grid-template-columns: repeat(4, 1fr);
   gap: 2rem;
   margin-bottom: 4rem;
 }

 .footer-col h4 {
   margin-bottom: 1.5rem;
   font-weight: 600;
 }

 .footer-col ul {
   list-style: none;
 }

 .footer-col ul li {
   margin-bottom: 0.75rem;
 }

 .footer-col ul li a {
   text-decoration: none;
   color: var(--text-muted);
   font-size: 0.875rem;
 }

 .footer-bottom {
   display: flex;
   justify-content: space-between;
   align-items: center;
   color: var(--text-muted);
   font-size: 0.875rem;
 }

