.deals-banner {
  background: var(--primary);
  color: white;
  padding: 3rem;
  border-radius: 1rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.deals-text h2 {
  font-size: 2.25rem;
  margin-bottom: 0.5rem;
}

